<section class="panel visitor-profile"><a href="<?=esc(admin_url())?>#visitor-list" class="back-link">← Svi posjetioci</a><div class="panel-heading"><div><div class="eyebrow">POJEDINAČNI TRAG POSJETIOCA</div><h1>Posjetilac #<?=esc(strtoupper(substr($detail['id'],0,8)))?></h1><p class="muted"><?=esc($detail['ip'])?> · <?=esc($countries[$detail['country']]??$detail['country'])?> · <?=esc($detail['device'].' / '.$detail['os'].' / '.$detail['browser'])?></p></div><span class="tag"><?=count($detail['sessions'])>1?'Vratio se na stranicu':'Prva zabilježena posjeta'?></span></div><div class="session-meta"><span class="tag">Prvi put: <?=esc(moment($detail['first']))?></span><span class="tag">Posljednja aktivnost: <?=esc(moment($detail['last']))?></span><span class="tag">Vrijeme: Sarajevo</span></div><p class="muted">Procijenjeni trag prema IP adresi, uređaju i pregledniku. Više osoba na istoj mreži i s istim vrstama uređaja može dijeliti trag; promjena IP-a može napraviti novi trag.</p></section>
<div class="kpis visitor-kpis"><?php foreach([['Posjete',count($detail['sessions'])],['Povratci',max(0,count($detail['sessions'])-1)],['Otvorene stranice',$detail['pages']],['Klikovi',$detail['clicks']],['Otvoreni / kliknuti modeli',count($detail['models'])],['Otvorene / kliknute slike',count($detail['photos'])],['Ukupno aktivno vrijeme',duration($detail['seconds'])],['Izvori dolaska',count($detail['sources'])]] as [$title,$value]):?><div class="kpi"><span><?=esc($title)?></span><strong><?=esc($value)?></strong></div><?php endforeach;?></div>
<section class="panel"><h2>Koje djevojke je otvarao i kliknuo</h2><div class="visitor-models"><?php foreach($detail['models'] as $id=>$model):?><article class="visitor-model"><img src="<?=esc($media[$id]['image']??'')?>" alt="<?=esc($names[$id]??$id)?>" loading="lazy"><div><h3><?=esc($names[$id]??$id)?></h3><p><?=$model['views']?> otvaranja · <?=$model['clicks']?> klikova<br><?=count($model['photos'])?> pojedinačnih fotografija<br><strong><?=duration($model['seconds'])?></strong> aktivnog vremena</p></div></article><?php endforeach;?></div><?php if(!$detail['models']):?><p class="muted">Nema zabilježenih otvaranja ili klikova na modele.</p><?php endif;?></section>
<section class="panel"><h2>Fotografije koje je otvarao</h2><p class="muted">Vrijeme se mjeri dok je otvorena fotografija aktivna. Ono je dio vremena na modelu, ne dodatno vrijeme. Pojedinačne fotografije i njihovo vrijeme prate se od ove nadogradnje.</p><div class="visitor-photos"><?php foreach($detail['photos'] as $path=>$photo):$photoNumber=array_search($path,$media[$photo['creator']]['gallery']??[],true);?><article class="visitor-photo"><a href="<?=esc($path)?>" target="_blank" rel="noopener noreferrer"><img src="<?=esc($path)?>" alt="<?=esc(($names[$photo['creator']]??'').' — fotografija '.($photoNumber===false?'':$photoNumber+1))?>" loading="lazy"></a><div><strong><?=esc($names[$photo['creator']]??'')?> · slika <?=$photoNumber===false?'—':$photoNumber+1?></strong><small><?=$photo['views']?> otvaranja · <?=$photo['clicks']?> klikova</small><span><?=duration($photo['seconds'])?> aktivnog gledanja</span></div></article><?php endforeach;?></div><?php if(!$detail['photos']):?><p class="muted">Nema zabilježenih pojedinačnih fotografija. Za starije posjete dostupni su ranije zabilježeni modeli i klikovi; detalje gledanja slika nije moguće naknadno rekonstruisati.</p><?php endif;?></section>
<section class="panel"><h2>Sve posjete ovog traga</h2><?php foreach($sessions as $sid=>$s):if($s['visitor']!==$visitorId)continue;?><details><summary><?=esc(moment($s['first']))?> · <?=$s['returning']?'Ponovna posjeta':'Prva posjeta'?> · <?=duration($s['seconds'])?> · <?=esc($s['source'])?></summary><div class="session-meta"><span class="tag"><?=esc($s['host'])?></span><span class="tag">Do: <?=esc(moment($s['last']))?></span><?php foreach($s['utm'] as $k=>$value):if($value==='')continue;?><span class="tag">UTM <?=esc($k)?>: <?=esc($value)?></span><?php endforeach;?></div><div class="journey"><strong>Ulaz:</strong> <?=esc($s['entry'])?><br><strong>Putanja:</strong> <?=esc(implode(' → ',$s['pages']))?><br><strong>Djevojke:</strong> <?=esc(implode(', ',array_map(fn($id)=>$names[$id]??$id,array_keys($s['creators']))))?:'—'?></div></details><?php endforeach;?></section>
<section class="panel"><h2>Hronologija radnji</h2><p class="muted">Najnovije radnje su prve. Vrijeme zadržavanja je sabrano iznad; tehnički intervali mjerenja ne zatrpavaju ovu listu.</p><div class="table-wrap"><table><thead><tr><th>Vrijeme · Sarajevo</th><th>Radnja</th><th>Model / fotografija</th><th>Stranica</th></tr></thead><tbody><?php foreach($timelineRows as $event):$label=['page_view'=>'Otvorena stranica','creator_view'=>'Otvoren profil','photo_view'=>'Otvorena fotografija'][$event['type']]??$event['action'];?><tr><td><?=esc(moment($event['time'],true))?></td><td><?=esc($label)?></td><td><?php if($event['photo']):?><img class="timeline-thumb" src="<?=esc($event['photo'])?>" alt="" loading="lazy"><?php endif;?><?=esc($names[$event['creator']]??'—')?></td><td class="wrap"><?=esc($event['host'].$event['page'])?></td></tr><?php endforeach;?></tbody></table></div><div class="pagination"><?php if($eventPage>1):?><a class="button outline" href="<?=esc(admin_url($visitorId,['ep'=>$eventPage-1]))?>">← Novije radnje</a><?php endif;?><span>Stranica <?=$eventPage?> / <?=$eventPages?></span><?php if($eventPage<$eventPages):?><a class="button outline" href="<?=esc(admin_url($visitorId,['ep'=>$eventPage+1]))?>">Starije radnje →</a><?php endif;?></div></section>
